export function shippingCost(weight, express) {
  let total;
  if (weight <= 0) {
    total = 0;
  } else {
    if (express === true) {
      total = 10 + weight * 3;
    } else {
      total = 5 + weight * 2;
    }
  }
  return total;
}

import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { shippingCost } from './shipping.mjs';
const weights = [-2, 0, 1, 1.25];
const standard = weights.map(weight => shippingCost(weight, false));
const express = weights.map(weight => shippingCost(weight, true));
assert.deepEqual(standard, [0, 0, 7, 7.5]);
assert.deepEqual(express, [0, 0, 13, 13.75]);
const nonBooleanExpress = [1, 'yes', undefined, null].map(flag => shippingCost(1, flag));
assert.deepEqual(nonBooleanExpress, [7, 7, 7, 7]);
const source = readFileSync('shipping.mjs', 'utf8');
assert.match(source, /export function shippingCost/);
assert.ok(!/\belse\b/.test(source), 'Use early returns rather than nested else branches');
assert.ok(!/\blet total\b/.test(source), 'Remove the redundant accumulator');
const report = { cases: 12, standard, express, nonBooleanExpress, earlyReturns: true };
writeFileSync('shipping-verification.json', JSON.stringify(report) + '\n');
console.log('Shipping parity: 12 boundary cases; early returns verified');

